def leaf_value(kind: str, aux, raw: int):
    """Validate and convert one little-endian symbolic leaf."""
    if kind == 'b':
        if raw > 1:
            raise InventoryError('boolean object must be 0 or 1')
        return raw != 0
    if kind == 'c':
        if raw > 255:
            raise InventoryError('character object out of range')
        return chr(raw)
    if kind == 'i':
        if raw >> aux:
            raise InventoryError('integer object has padding bits set')
        return raw
    if kind == 'e':
        if raw >= len(aux):
            raise InventoryError('enumeration index out of range')
        return aux[raw]
    raise InventoryError('unknown leaf kind')


class _Cursor(object):
    __slots__ = ('nums', 'pos')

    def __init__(self, nums):
        self.nums = nums
        self.pos = 0

    def take(self, template):
        kind = template[0]
        if kind == 'i':
            value = self.nums[self.pos]
            self.pos += 1
            return value
        if kind == 'b':
            value = self.nums[self.pos]
            self.pos += 1
            return value != 0
        if kind == 'c':
            value = chr(self.nums[self.pos])
            self.pos += 1
            return value
        if kind == 'e':
            value = template[1][self.nums[self.pos]]
            self.pos += 1
            return value
        if kind == 's':
            start = self.pos
            size = template[1]
            end = start + size
            self.pos = end
            if size == 0:
                return ""
            window = self.nums[start:end]
            try:
                stop = window.index(0)
            except ValueError:
                stop = size
            return bytes(window[:stop]).decode('latin-1')
        if kind == 'a':
            count = template[1]
            if count == 0:
                return []
            sub = template[2]
            start = self.pos
            stop = start + count
            inner = sub[0]
            if inner == 'i':
                # A run of plain integers is one C level slice.
                self.pos = stop
                return self.nums[start:stop]
            window = self.nums[start:stop]
            if inner == 'c':
                self.pos = stop
                return list(bytes(window).decode('latin-1'))
            if inner == 'b':
                self.pos = stop
                return [value != 0 for value in window]
            if inner == 'e':
                self.pos = stop
                values = sub[1]
                return [values[value] for value in window]
            self.pos = start
            take = self.take
            return [take(sub) for _ in range(count)]
        if kind == 't':
            return {name: self.take(sub) for name, sub in template[1]}
        return None


def make_template(node_type: Type):
    """Build the cursor template that recovers values for a type."""
    inner = Type.inner(node_type)
    if isinstance(inner, Void):
        return ('v',)
    if isinstance(inner, Bool):
        return ('b',)
    if isinstance(inner, Char):
        return ('c',)
    if isinstance(inner, Int):
        return ('i',)
    if isinstance(inner, Enum):
        return ('e', inner.values)
    if isinstance(inner, String):
        return ('s', inner.maxsize)
    if isinstance(inner, Array):
        count = inner.maxsize
        if count == 0:
            return ('a', 0, None)
        return ('a', count, make_template(inner.element_type))
    if isinstance(inner, Struct):
        return ('t', tuple((name, make_template(field))
                           for name, field in inner.fields.items()))
    raise Exception(f'unknown type {inner!r}')


